for (size_t i = start; i < end; ++i) {
    Particle& pi = particles[i];
    glm::vec3 pressureForce(0.0f);
    glm::vec3 viscosityForce(0.0f);

    // Get neighbors from particle table
    uint32_t currentIndex = static_cast<uint32_t>(i);
    uint32_t neighborIndex = particleTable[currentIndex];

    while (neighborIndex != 0xFFFFFFFF && neighborIndex < particleCount) {
        if (neighborIndex == currentIndex) {
            neighborIndex = particleTable[neighborIndex + 1];
            continue;
        }

        Particle& pj = particles[neighborIndex];
        glm::vec3 r = pi.position - pj.position;
        float r2 = glm::dot(r, r);

        if (r2 < h2 && r2 > 0.0f) {
            float r_len = std::sqrt(r2);

            // Pressure force
            float pressureTerm = (pi.pressure + pj.pressure) / (2.0f * pi.density * pj.density);
            glm::vec3 pressureDir = r / r_len;
            pressureForce += -mass * pressureTerm * spikyGrad * (h - r_len) * (h - r_len) * pressureDir;

            // Viscosity force
            glm::vec3 velocityDiff = pj.velocity - pi.velocity;
            viscosityForce += mass * viscosity * (velocityDiff / pi.density) * spikyLap * (h - r_len);
        }

        neighborIndex = particleTable[neighborIndex + 1];
    }

    pi.force = pressureForce + viscosityForce;
}

